bool init(const boot::Framebuffer& fb){screen=fb;ok=fb.valid&&fb.width>=640&&fb.height>=480&&fb.bpp==32;load_theme();mode=Mode::Boot;app=App::None;boot_start=arch::ticks();line_count=0;addline("IrOS 0.3 terminal");addline("Persistent IrFS + RTL8139 networking");dirty=true;return ok;}bool ready(){return ok;}void mark_dirty(){dirty=true;}void update(){if(mode==Mode::Boot){uint64_t d=arch::ticks()-boot_start;if(d>60){mode=Mode::Login;dirty=true;}else dirty=true;}}void render(){if(!ok||!dirty)return;if(mode==Mode::Boot)boot_screen();else if(mode==Mode::Login)login_screen();else{wallpaper();desktop_icons();taskbar();if(app==App::Files)files();else if(app==App::Terminal)terminal();else if(app==App::System)system_app();else if(app==App::Settings)settings();else if(app==App::Editor)editor();startmenu();}auto m=input::mouse_state();cursor(m.x,m.y);copy_to_fb();dirty=false;}
void on_key(const input::KeyEvent& e){if(!e.pressed)return;if(mode==Mode::Boot)return;if(mode==Mode::Login){if(e.ch=='\n'||e.scancode==0x39)login();return;}if(dialog_kind){if(e.scancode==1){dialog_kind=0;dialog_len=0;dialog[0]=0;dirty=true;return;}if(e.ch=='\b'){if(dialog_len)dialog[--dialog_len]=0;dirty=true;return;}if(e.ch=='\n'){if(dialog_len){char p[160];join_path(file_path,dialog,p,sizeof(p));if(dialog_kind==1)vfs::create(p);else vfs::mkdir(p);}dialog_kind=0;dialog_len=0;dialog[0]=0;file_sel=0;dirty=true;return;}if(e.ch>=32&&e.ch<127&&e.ch!='/'&&dialog_len+1<sizeof(dialog)){dialog[dialog_len++]=e.ch;dialog[dialog_len]=0;dirty=true;}return;}if(app==App::Editor){if(e.ctrl&&(e.ch=='s'||e.ch=='S')){save_editor();dirty=true;return;}if(e.scancode==1){launch(App::Files);return;}if(e.ch=='\b'){if(edit_len){edit_buf[--edit_len]=0;edit_dirty=true;dirty=true;}return;}if((e.ch=='\n'||(e.ch>=32&&e.ch<127))&&edit_len+1<sizeof(edit_buf)){edit_buf[edit_len++]=e.ch;edit_buf[edit_len]=0;edit_dirty=true;dirty=true;}return;}if(e.scancode==0x3B){launch(App::Files);return;}if(e.scancode==0x3C){launch(App::Terminal);return;}if(e.scancode==0x3D){launch(App::System);return;}if(e.scancode==0x3E){launch(App::Settings);return;}if(e.scancode==1){if(app!=App::None){app=App::None;start_menu=false;}else start_menu=!start_menu;dirty=true;return;}if(app==App::Settings){if(e.scancode==0x4B){theme_id=(theme_id+3)&3;dirty=true;}else if(e.scancode==0x4D){theme_id=(theme_id+1)&3;dirty=true;}else if(e.ch=='\n'){save_theme();dirty=true;}return;}if(app==App::Files){int id=vfs::resolve(file_path),c=vfs::child_count(id);if(e.scancode==0x48&&file_sel>0)--file_sel;else if(e.scancode==0x50&&file_sel+1<c)++file_sel;else if(e.ch=='\b')parent_path();else if(e.ch=='n'||e.ch=='N'){dialog_kind=1;dialog_len=0;dialog[0]=0;}else if(e.ch=='m'||e.ch=='M'){dialog_kind=2;dialog_len=0;dialog[0]=0;}else if(e.scancode==0x53&&c){auto* n=vfs::child(id,file_sel);if(n){char p[160];join_path(file_path,n->name,p,sizeof(p));vfs::remove(p);if(file_sel>=vfs::child_count(id)&&file_sel>0)--file_sel;}}else if(e.ch=='\n'&&c){auto* n=vfs::child(id,file_sel);if(n){char p[160];join_path(file_path,n->name,p,sizeof(p));if(n->dir){ir::strcpy(file_path,p,sizeof(file_path));file_sel=0;}else open_editor(p);}}dirty=true;return;}if(app!=App::Terminal)return;if(e.ch=='\b'){if(cmdlen)cmd[--cmdlen]=0;dirty=true;return;}if(e.ch=='\n'){char shown[84]="IROS> ";ir::strcpy(shown+6,cmd,sizeof(shown)-6);addline(shown);shell(cmd);cmdlen=0;cmd[0]=0;dirty=true;return;}if(e.ch>=32&&e.ch<127&&cmdlen+1<sizeof(cmd)){cmd[cmdlen++]=e.ch;cmd[cmdlen]=0;dirty=true;}}
void on_mouse(const input::MouseState& m){bool click=(m.buttons&1)&&!(prev_buttons&1);prev_buttons=m.buttons;if(!click){if(m.changed)dirty=true;return;}if(mode==Mode::Login){int w=420,h=280,x=(W()-w)/2,y=(H()-h)/2-20;if(inside(m.x,m.y,x+105,y+210,210,42))login();return;}if(mode!=Mode::Desktop)return;int ty=H()-44;if(inside(m.x,m.y,8,ty+6,88,32)){start_menu=!start_menu;dirty=true;return;}if(inside(m.x,m.y,108,ty+6,100,32)){launch(App::Files);return;}if(inside(m.x,m.y,214,ty+6,130,32)){launch(App::Terminal);return;}if(inside(m.x,m.y,350,ty+6,112,32)){launch(App::System);return;}if(inside(m.x,m.y,468,ty+6,126,32)){launch(App::Settings);return;}if(start_menu){int sy=H()-44-292;if(inside(m.x,m.y,18,sy+58,285,38)){launch(App::Files);return;}if(inside(m.x,m.y,18,sy+96,285,38)){launch(App::Terminal);return;}if(inside(m.x,m.y,18,sy+134,285,38)){launch(App::System);return;}if(inside(m.x,m.y,18,sy+172,285,38)){launch(App::Settings);return;}if(inside(m.x,m.y,18,sy+220,285,45)){mode=Mode::Login;app=App::None;start_menu=false;dirty=true;return;}}if(app==App::Settings){int x=54,y=48;for(int i=0;i<4;++i){int bx=x+34+i*190,by=y+120;if(inside(m.x,m.y,bx,by,160,120)){theme_id=(uint8_t)i;save_theme();dirty=true;return;}}}if(app==App::Files){int x=54,y=48,w=W()-108,h=H()-110;if(inside(m.x,m.y,x+w-34,y+5,24,24)){app=App::None;dirty=true;return;}int id=vfs::resolve(file_path),yy=y+128;for(int i=0;i<vfs::child_count(id)&&yy<y+h-35;++i,yy+=28)if(inside(m.x,m.y,x+18,yy-4,w-36,24)){if(file_sel==i){auto* n=vfs::child(id,i);if(n){char p[160];join_path(file_path,n->name,p,sizeof(p));if(n->dir){ir::strcpy(file_path,p,sizeof(file_path));file_sel=0;}else open_editor(p);}}else file_sel=i;dirty=true;return;}}if(app!=App::None){int x=54,y=48,w=W()-108;if(inside(m.x,m.y,x+w-34,y+5,24,24)){app=App::None;dirty=true;return;}}if(app==App::None){if(inside(m.x,m.y,28,34,100,94)){launch(App::Files);return;}if(inside(m.x,m.y,28,132,120,94)){launch(App::Terminal);return;}if(inside(m.x,m.y,28,226,120,94)){launch(App::Settings);return;}}dirty=true;}
